 #include &lt;bits/stdc++.h&gt; using namespace std; class Solution { public: // ================================================================ // 版本一：四条边界收缩，额外空间 O(1) // ================================================================ vector&lt;int&gt; spiralOrder(vector&lt;vector&lt;int&gt;&gt;&amp; matrix) { vector&lt;int&gt; ans; int rows = (int)matrix.size(); if (rows == 0) { return ans; // 空矩阵 } int cols = (int)matrix[0].size(); int top = 0; // 上边界（含） int bottom = rows - 1; // 下边界（含） int left = 0; // 左边界（含） int right = cols - 1; // 右边界（含） while (top &lt;= bottom &amp;&amp; left &lt;= right) { // ---------- ① 上边：从左到右 ---------- for (int j = left; j &lt;= right; j++) { ans.push_back(matrix[top][j]); } top++; // 这一行收完了，上边界下移 // ---------- ② 右边：从上到下 ---------- // 起点是 top+1，因为右上角那个元素在第一步已经收过了 for (int i = top; i &lt;= bottom; i++) { ans.push_back(matrix[i][right]); } right--; // 这一列收完了，右边界左移 // ---------- ③ 下边：从右到左 ---------- // 必须先判：如果上边界已经越过下边界，说明这一圈只剩一行， // 而这一行在第一步就收完了，再走一遍就会重复 if (top &lt;= bottom) { // 起点是 right-1，因为右下角那个元素在第二步已经收过了 for (int j = right; j &gt;= left; j--) { ans.push_back(matrix[bottom][j]); } bottom--; // 这一行收完了，下边界上移 } // ---------- ④ 左边：从下到上 ---------- // 同理，必须先判：如果左边界已经越过右边界，说明这一圈只剩一列， // 而这一列在第二步就收完了，再走一遍就会重复 if (left &lt;= right) { // 起点是 bottom-1，因为左下角那个元素在第三步已经收过了 for (int i = bottom; i &gt;= top; i--) { ans.push_back(matrix[i][left]); } left++; // 这一列收完了，左边界右移 } } return ans; } // ================================================================ // 版本二：方向数组 + visited 标记，&#34;撞墙就右转&#34;，O(m·n) 空间 // 方向顺序固定为 右 → 下 → 左 → 上，撞到边界或已访问就转 90° // ================================================================ vector&lt;int&gt; spiralOrder_v2(vector&lt;vector&lt;int&gt;&gt;&amp; matrix) { vector&lt;int&gt; ans; int rows = (int)matrix.size(); if (rows == 0) { return ans; } int cols = (int)matrix[0].size(); vector&lt;vector&lt;bool&gt;&gt; visited(rows, vector&lt;bool&gt;(cols, false)); // 右、下、左、上 —— 顺时针转 90° 就是 dir = (dir + 1) % 4 int dr[4] = {0, 1, 0, -1}; // 行增量 int dc[4] = {1, 0, -1, 0}; // 列增量 int dir = 0; // 当前朝向 int r = 0, c = 0; // 当前所在格子 for (int step = 0; step &lt; rows * cols; step++) { ans.push_back(matrix[r][c]); visited[r][c] = true; int nr = r + dr[dir]; int nc = c + dc[dir]; // 下一个格子越界或者已经走过 → 右转 if (nr &lt; 0 || nr &gt;= rows || nc &lt; 0 || nc &gt;= cols || visited[nr][nc]) { dir = (dir + 1) % 4; nr = r + dr[dir]; nc = c + dc[dir]; } r = nr; c = nc; } return ans; } }; // 本地测试：先读行数 r、列数 c，再读 r*c 个元素（按行）；输出螺旋顺序数组 // 同时跑两个版本并比对结果，两个实现思路完全独立，适合互相验证 int main() { ios::sync_with_stdio(false); cin.tie(nullptr); int r, c; if (!(cin &gt;&gt; r &gt;&gt; c)) return 0; vector&lt;vector&lt;int&gt;&gt; matrix(r, vector&lt;int&gt;(c)); for (int i = 0; i &lt; r; ++i) for (int j = 0; j &lt; c; ++j) cin &gt;&gt; matrix[i][j]; vector&lt;int&gt; ans1 = Solution().spiralOrder(matrix); vector&lt;int&gt; ans2 = Solution().spiralOrder_v2(matrix); if (ans1 != ans2) { cout &lt;&lt; &#34;MISMATCH
