 #include &lt;bits/stdc++.h&gt; using namespace std; class Solution { public: // ================================================================ // 版本一：排序 + 额外结果数组 // 按左端点排序后，从左到右一趟扫描，边扫边合并 // ================================================================ vector&lt;vector&lt;int&gt;&gt; merge(vector&lt;vector&lt;int&gt;&gt;&amp; intervals) { int n = (int)intervals.size(); if (n == 0) { return {}; } // 按左端点升序排序 sort(intervals.begin(), intervals.end(), [](const vector&lt;int&gt;&amp; a, const vector&lt;int&gt;&amp; b) { return a[0] &lt; b[0]; }); vector&lt;vector&lt;int&gt;&gt; ans; for (int i = 0; i &lt; n; i++) { if (ans.empty() || ans.back()[1] &lt; intervals[i][0]) { // 不重叠：把它作为一个新的段放进去 ans.push_back(intervals[i]); } else { // 重叠：把右端点扩展到两者的较大值 // 必须取 max，因为可能是 [1,10] 和 [2,3] 这种被完全包含的情况 ans.back()[1] = max(ans.back()[1], intervals[i][1]); } } return ans; } // ================================================================ // 版本二：原地合并，省掉结果数组 // 用 write 指向&#34;下一个要写入的位置&#34;，答案直接在 intervals 的前 write 个位置里 // 结束时 resize(write) 把尾巴截掉 // 注意：这个函数会修改 intervals // ================================================================ vector&lt;vector&lt;int&gt;&gt; merge_v2(vector&lt;vector&lt;int&gt;&gt;&amp; intervals) { int n = (int)intervals.size(); if (n == 0) { return {}; } sort(intervals.begin(), intervals.end(), [](const vector&lt;int&gt;&amp; a, const vector&lt;int&gt;&amp; b) { return a[0] &lt; b[0]; }); int write = 0; // 下一个要写入的位置 for (int i = 0; i &lt; n; i++) { // write == 0 表示还没有任何一段，先放一段进去 // intervals[write - 1][1] 是&#34;当前正在合并的那一段&#34;的右端点 if (write == 0 || intervals[write - 1][1] &lt; intervals[i][0]) { intervals[write] = intervals[i]; // 不重叠，开新段 write++; } else { // 重叠，扩展当前段的右端点 intervals[write - 1][1] = max(intervals[write - 1][1], intervals[i][1]); } } intervals.resize(write); return intervals; } }; // 本地测试：输入 n，然后 n 对整数（每对是一个区间）；每行输出合并后的一个区间 // 同时跑两个版本并比对结果，版本二会改数组所以各用一份副本 int main() { ios::sync_with_stdio(false); cin.tie(nullptr); int n; if (!(cin &gt;&gt; n)) return 0; vector&lt;vector&lt;int&gt;&gt; intervals(n, vector&lt;int&gt;(2)); for (int i = 0; i &lt; n; ++i) cin &gt;&gt; intervals[i][0] &gt;&gt; intervals[i][1]; vector&lt;vector&lt;int&gt;&gt; copy = intervals; // 给版本二留一份 vector&lt;vector&lt;int&gt;&gt; ans1 = Solution().merge(intervals); vector&lt;vector&lt;int&gt;&gt; ans2 = Solution().merge_v2(copy); if (ans1 != ans2) { cout &lt;&lt; &#34;MISMATCH
&#34;; cout &lt;&lt; &#34;v1:&#34;; for (const vector&lt;int&gt;&amp; v : ans1) cout &lt;&lt; &#34; [&#34; &lt;&lt; v[0] &lt;&lt; &#34;,&#34; &lt;&lt; v[1] &lt;&lt; &#34;]&#34;; cout &lt;&lt; &#34;
v2:&#34;; for (const vector&lt;int&gt;&amp; v : ans2) cout &lt;&lt; &#34; [&#34; &lt;&lt; v[0] &lt;&lt; &#34;,&#34; &lt;&lt; v[1] &lt;&lt; &#34;]&#34;; cout &lt;&lt; &#39;
&#39;; return 0; } if (ans1.empty()) { cout &lt;&lt; &#34;none
&#34;; } else { for (const vector&lt;int&gt;&amp; v : ans1) cout &lt;&lt; v[0] &lt;&lt; &#39; &#39; &lt;&lt; v[1] &lt;&lt; &#39;
&#39;; } return 0; }

