 #include &lt;bits/stdc++.h&gt; using namespace std; class Solution { public: // ================================================================ // 版本一：两个布尔数组，额外空间 O(m + n)，最直观 // ================================================================ void setZeroes_v1(vector&lt;vector&lt;int&gt;&gt;&amp; matrix) { int rows = (int)matrix.size(); if (rows == 0) { return; } int cols = (int)matrix[0].size(); vector&lt;bool&gt; rowHasZero(rows, false); // 第 i 行要不要清零 vector&lt;bool&gt; colHasZero(cols, false); // 第 j 列要不要清零 // 第一遍：只做标记，不改矩阵 for (int i = 0; i &lt; rows; i++) { for (int j = 0; j &lt; cols; j++) { if (matrix[i][j] == 0) { rowHasZero[i] = true; colHasZero[j] = true; } } } // 第二遍：按标记统一清零 for (int i = 0; i &lt; rows; i++) { for (int j = 0; j &lt; cols; j++) { if (rowHasZero[i] || colHasZero[j]) { matrix[i][j] = 0; } } } } // ================================================================ // 版本二：借用第一行、第一列当标记位，额外空间 O(1)（正解） // ================================================================ void setZeroes(vector&lt;vector&lt;int&gt;&gt;&amp; matrix) { int rows = (int)matrix.size(); if (rows == 0) { return; } int cols = (int)matrix[0].size(); // ---------- 第 ① 步：先单独记下第一行、第一列原本有没有 0 ---------- // 这一步是整个算法的地基。不能省，也不能用 matrix[0][0] 代替： // 一个格子里装不下&#34;第一行有 0&#34;和&#34;第一列有 0&#34;这两条独立信息。 bool firstRowHasZero = false; bool firstColHasZero = false; for (int j = 0; j &lt; cols; j++) { if (matrix[0][j] == 0) { firstRowHasZero = true; break; } } for (int i = 0; i &lt; rows; i++) { if (matrix[i][0] == 0) { firstColHasZero = true; break; } } // ---------- 第 ② 步：从 (1,1) 开始打标记 ---------- // 遇到 0 就在它所在行的行首、所在列的列首各打一个 0 // 注意从 (1,1) 起，跳过第一行第一列——它们是标记区，不是数据区 for (int i = 1; i &lt; rows; i++) { for (int j = 1; j &lt; cols; j++) { if (matrix[i][j] == 0) { matrix[i][0] = 0; // 标记：第 i 行要清零 matrix[0][j] = 0; // 标记：第 j 列要清零 } } } // ---------- 第 ③ 步：按标记把内部数据清零 ---------- // 判断是&#34;或&#34;：只要所在行或所在列被标记了，自己就要变 0 for (int i = 1; i &lt; rows; i++) { for (int j = 1; j &lt; cols; j++) { if (matrix[i][0] == 0 || matrix[0][j] == 0) { matrix[i][j] = 0; } } } // ---------- 第 ④ 步：最后处理第一行和第一列自己 ---------- // 必须放在第③步之后。标记位就存在第一行、第一列里， // 先清零就把标记擦掉了，第③步会全部失效。 if (firstRowHasZero) { for (int j = 0; j &lt; cols; j++) { matrix[0][j] = 0; } } if (firstColHasZero) { for (int i = 0; i &lt; rows; i++) { matrix[i][0] = 0; } } } }; // 本地测试：先读行数 r、列数 c，再读 r*c 个元素（按行）；输出置零后的矩阵 // 同时跑两个版本并比对结果，版本一思路更直白，适合当版本二的对照 int main() { ios::sync_with_stdio(false); cin.tie(nullptr); int r, c; if (!(cin &gt;&gt; r &gt;&gt; c)) return 0; vector&lt;vector&lt;int&gt;&gt; matrix(r, vector&lt;int&gt;(c)); for (int i = 0; i &lt; r; ++i) for (int j = 0; j &lt; c; ++j) cin &gt;&gt; matrix[i][j]; vector&lt;vector&lt;int&gt;&gt; copy = matrix; // 两版都是原地修改，各用一份 Solution().setZeroes_v1(matrix); Solution().setZeroes(copy); if (matrix != copy) { cout &lt;&lt; &#34;MISMATCH
