 #include &lt;bits/stdc++.h&gt; using namespace std; class Solution { public: // ================================================================ // 版本一：字符 -&gt; 位置列表（你的写法） // ts : t 的哈希表，字符 -&gt; 需要几个 // window : 当前窗口的哈希表，字符 -&gt; 它在 s 中出现的位置（位置递增压入） // covered : 窗口里每种字符的个数是否都已达到 ts 的要求 // leftmost : 窗口最靠前的位置，也就是当前窗口的左端点 // 每读到一个 t 里的字符就压进 window；只要 covered，说明窗口刚好覆盖 t， // 记下长度，然后删掉&#34;最靠前位置&#34;的那个字符，把窗口往右缩一格，再判定一次。 // ================================================================ string minWindow(string s, string t) { unordered_map&lt;char, int&gt; ts; // t 的哈希表：字符 -&gt; 需要几个 for (char c : t) ts[c]++; unordered_map&lt;char, vector&lt;int&gt;&gt; window; // 当前窗口：字符 -&gt; 它出现的位置（递增） int minlength = INT_MAX; // 最小覆盖子串的长度 int start = 0; // 最小覆盖子串的起点 string ans = &#34;&#34;; // 窗口是否已经覆盖 t 的全部字符和个数 auto covered = [&amp;]() -&gt; bool { for (auto&amp; p : ts) { auto it = window.find(p.first); if (it == window.end() || (int)it-&gt;second.size() &lt; p.second) return false; } return true; }; // 窗口最靠前的字符及其位置 auto leftmost = [&amp;]() -&gt; pair&lt;char, int&gt; { pair&lt;char, int&gt; res = {0, INT_MAX}; for (auto&amp; p : window) if (!p.second.empty() &amp;&amp; p.second.front() &lt; res.second) res = {p.first, p.second.front()}; return res; }; for (int right = 0; right &lt; (int)s.size(); right++) { if (!ts.count(s[right])) continue; // 不是 t 里的字符，不进窗口 window[s[right]].push_back(right); // 压入当前位置 while (covered()) { // 一致：记下长度，然后删掉最靠前位置的字符 auto [leftChar, leftPos] = leftmost(); int len = right - leftPos + 1; if (len &lt; minlength) { minlength = len; start = leftPos; } window[leftChar].erase(window[leftChar].begin()); } } if (minlength == INT_MAX) return ans; return s.substr(start, minlength); } // ================================================================ // 版本二：数组 + formed 计数器，O(|s|)，面试写的版本（对应上面 4 条提示） // need[c] : t 里字符 c 需要几个 // cnt[c] : 当前窗口里字符 c 有几个 // required : t 里有多少种不同字符 // formed : 已经&#34;凑够数量&#34;的字符种数 // formed == required 等价于&#34;窗口覆盖了 t&#34;，O(1) 就能判断，不用扫字符表。 // 非 t 字符的 need 是 0，进窗/出窗时被 need[c] &gt; 0 挡住，cnt 不动， // 所以不需要像版本一那样显式过滤，它们天然对 formed 没有影响。 // 字符统一用 int 变量接住再当下标：题目保证 s 和 t 只含英文字母， // ASCII 码都落在 0~127，用 int 接一下既不会越界，也不会触发 gcc 的 // -Wchar-subscripts 警告（char 在某些平台是有符号的，编译器会担心下标为负）。 // ================================================================ string minWindow_v2(string s, string t) { // need[c] = t 里字符 c 需要几个 int need[128] = {0}; for (int i = 0; i &lt; (int)t.size(); i++) { int c = t[i]; need[c]++; } // required = t 里有几种不同的字符 int required = 0; for (int c = 0; c &lt; 128; c++) { if (need[c] &gt; 0) { required++; } } int cnt[128] = {0}; // cnt[c] = 当前窗口里字符 c 有几个 int formed = 0; // 窗口里&#34;数量已经够了&#34;的字符有几种 int left = 0; // 窗口左端点 int start = 0; // 答案的起点 int minlength = INT_MAX; // 答案的长度 for (int right = 0; right &lt; (int)s.size(); right++) { // ---------- 第 1 步：right 位置的字符进窗 ---------- // 提示 2：right 右移扩张，直到窗口覆盖 t int in = s[right]; if (need[in] &gt; 0) { // 不是 t 里的字符，不参与统计 cnt[in]++; if (cnt[in] == need[in]) { // 这个字符的数量刚好够了 formed++; } } // ---------- 第 2 步：窗口已经覆盖 t，就把 left 往右推，尽量缩短 ---------- // 提示 3：边收缩边记长度，直到刚好不再覆盖 while (formed == required) { int len = right - left + 1; if (len &lt; minlength) { // 记下更短的答案 minlength = len; start = left; } int out = s[left]; // left 位置的字符出窗 if (need[out] &gt; 0) { if (cnt[out] == need[out]) { // 它现在刚好够，出去就不够了 formed--; } cnt[out]--; } left++; } // 提示 4：left 收缩到不再覆盖后，right 继续右移，直到 s 末尾 } // ---------- 第 3 步：一次都没有覆盖成功过 ---------- if (minlength == INT_MAX) { return &#34;&#34;; } return s.substr(start, minlength); } }; // 本地测试：输入两个字符串 s 和 t；输出最小覆盖子串，不存在则输出 none // 同时跑两个版本并比对结果，方便验证优化版和原版等价 int main() { ios::sync_with_stdio(false); cin.tie(nullptr); string s, t; if (!(cin &gt;&gt; s &gt;&gt; t)) return 0; string ans1 = Solution().minWindow(s, t); string ans2 = Solution().minWindow_v2(s, t); if (ans1 != ans2) { cout &lt;&lt; &#34;MISMATCH: v1=&#34; &lt;&lt; (ans1.empty() ? &#34;none&#34; : ans1) &lt;&lt; &#34; v2=&#34; &lt;&lt; (ans2.empty() ? &#34;none&#34; : ans2) &lt;&lt; &#39;
&#39;; return 0; } if (ans1.empty()) { cout &lt;&lt; &#34;none
&#34;; } else { cout &lt;&lt; ans1 &lt;&lt; &#39;
&#39;; } return 0; }

